-- Market demand that ships with the site (lib/keywords/, /admin/keywords): the Google
-- Keyword Planner export of 2026-11-02 — Uzbekistan, all languages, Google search,
-- October 2025 – September 2026, 1913 keywords. Without it the «Talab tahlili» page stays
-- empty until someone uploads a file; with it the page opens with the market already read.
--
-- Rows are as the panel's own import stores them (normalized keyword, language, subject,
-- intent). Loaded only into an empty table: an import already made on this database wins,
-- and any later upload replaces these numbers the usual way.

do $$
declare imp bigint;
begin
  if exists (select 1 from keyword_imports) or exists (select 1 from keyword_stats) then
    return;
  end if;
    values ('Keyword_Stats_2026-11-02.csv', 1913, 1900, 'USD', false, '2026-11-02T21:32:33+05:00')
    returning id into imp;
  on conflict (keyword) do nothing;
end $$;
